"use client"

// Bollard UI — dependency-license-check · MIT licence · https://bollard-ui.vercel.app/components/dependency-license-check

import * as React from "react"
import { CircleCheck, Loader2, Package, Pin, Scale, ShieldAlert, Trash2 } from "lucide-react"

import { cn } from "@/lib/utils"
import { licenseText, reviewDependency, type DependencyInfo, type LicenseCategory, type LicenseLevel, type LicensePolicy, type LicenseReason } from "./license"

export { categorize, CUSTOM_LICENSE, licenseText, readLicense, reviewDependency, type DependencyInfo, type LicenseField, type LicenseCategory, type LicenseLevel, type LicensePolicy, type LicenseReading, type LicenseReason, type LicenseReview } from "./license"

/** Every visible string. `{license}`, `{chosen}`, `{project}`, `{from}`, `{version}`, `{count}` and `{total}` are filled in. */
export const DEPENDENCY_LICENSE_MESSAGES = {
  heading: "New dependencies",
  policy: { distributed: "Shipped to users", saas: "Hosted service", internal: "Internal only" } as Record<NonNullable<LicensePolicy["distribution"]>, string>,
  proprietary: "Closed source",
  reasons: {
    ok: "",
    allowed: "Approved by your team's policy.",
    chosen: "Dual-licensed: you can use it under {chosen}.",
    devOnly: "Dev only, so it isn't shipped and its copyleft doesn't reach your code.",
    denied: "{license} is on your team's deny list.",
    missing: "No license declared. Without one you have no permission to use it.",
    unknown: "“{license}” isn't a license this check recognises. Read its terms first.",
    weak: "Weak copyleft: fine to use unmodified, but changes to its own files must be shared.",
    gpl: "GPL: shipping it in closed-source code means releasing your source under the GPL.",
    gplSaas: "GPL: fine on servers you run, but not in code you ship to browsers or apps.",
    agpl: "AGPL: anyone who uses your app, even over the web, can ask for your full source.",
    copyleftInternal: "Copyleft, but fine while this stays internal. Check again before you ship it.",
    copyleftInOpenSource: "{license} would make the combined project {license} when distributed.",
    sourceAvailable: "Source-available, not open source. Check its terms before you ship it.",
    sourceAvailableSaas: "Source-available: it usually bars offering it as a hosted service.",
    custom: "Custom or paid terms (“{license}”). Read them before you add it.",
    incompatible: "{license} can't be combined with your {project} code.",
  } as Record<LicenseReason, string>,
  changed: "Was {from} up to {version}.",
  changedNoVersion: "Was {from} in the previous version.",
  categories: { permissive: "Permissive", weak: "Weak copyleft", unknown: "Unknown", strong: "Copyleft", network: "Network copyleft", "source-available": "Source-available", missing: "No license" } as Record<LicenseCategory, string>,
  dev: "dev",
  pin: "Stay on {version}",
  remove: "Remove",
  keep: "Keep",
  pinned: "Pinned to {version}, the last {from} release.",
  summaryBlocked: "{count} of {total} not allowed by your policy",
  summaryReview: "{count} of {total} to review",
  summaryOk: "Every license fits your policy",
  add: "Add dependencies",
  addAnyway: "Add anyway",
}

export type DependencyLicenseMessages = typeof DEPENDENCY_LICENSE_MESSAGES

const fill = (template: string, values: Record<string, string | number>) =>
  template.replace(/\{(\w+)\}/g, (match, key: string) => String(values[key] ?? match))

const CHIP: Record<LicenseCategory, string> = {
  permissive: "bg-emerald-500/15 text-emerald-800 dark:text-emerald-300",
  weak: "bg-sky-500/15 text-sky-800 dark:text-sky-300",
  unknown: "bg-amber-500/15 text-amber-800 dark:text-amber-300",
  strong: "bg-red-500/15 text-red-800 dark:text-red-300",
  network: "bg-red-500/15 text-red-800 dark:text-red-300",
  "source-available": "bg-amber-500/15 text-amber-800 dark:text-amber-300",
  missing: "bg-red-500/15 text-red-800 dark:text-red-300",
}
const TEXT: Record<LicenseLevel, string> = {
  ok: "text-muted-foreground",
  note: "text-muted-foreground",
  warn: "text-amber-700 dark:text-amber-400",
  block: "text-red-700 dark:text-red-400",
}
const fixClass =
  "inline-flex h-6 items-center gap-1 rounded-md border border-amber-500/40 px-2 font-medium text-amber-900 transition-colors hover:bg-amber-500/10 dark:text-amber-200 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
const blockFixClass =
  "inline-flex h-6 items-center gap-1 rounded-md border border-red-500/40 px-2 font-medium text-red-800 transition-colors hover:bg-red-500/10 dark:text-red-300 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
const ghostClass =
  "inline-flex h-6 items-center gap-1 rounded-md px-2 font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"

export interface DependencyLicenseCheckProps extends Omit<React.ComponentProps<"div">, "defaultValue" | "onChange"> {
  /** Controlled dependencies being added. */
  value?: DependencyInfo[]
  /** Initial dependencies when uncontrolled. */
  defaultValue?: DependencyInfo[]
  /** Called after Remove or "Stay on" with the new list. */
  onValueChange?: (dependencies: DependencyInfo[]) => void
  /** Your project's license, distribution and allow/deny lists. */
  policy?: LicensePolicy
  /** Called on Add. With problems left, the first click jumps to them and the second adds. May return a Promise. */
  onAdd?: (dependencies: DependencyInfo[]) => void | Promise<void>
  /** Any visible string; `reasons`, `categories` and `policy` may be partial. */
  messages?: Partial<Omit<DependencyLicenseMessages, "reasons" | "categories" | "policy">> & {
    reasons?: Partial<DependencyLicenseMessages["reasons"]>
    categories?: Partial<DependencyLicenseMessages["categories"]>
    policy?: Partial<DependencyLicenseMessages["policy"]>
  }
}

/**
 * Checks each dependency's license against your project before it is added: GPL or AGPL in
 * closed-source code, no license or one it doesn't recognise, source-available terms in a hosted
 * product, and a relicense since the previous version (offering to stay on the last version under
 * the old license). Dual licenses are read for the friendliest option, and dev-only copyleft passes.
 */
export function DependencyLicenseCheck({ value, defaultValue = [], onValueChange, policy = {}, onAdd, messages, className, ...props }: DependencyLicenseCheckProps) {
  const t = {
    ...DEPENDENCY_LICENSE_MESSAGES,
    ...messages,
    reasons: { ...DEPENDENCY_LICENSE_MESSAGES.reasons, ...messages?.reasons },
    categories: { ...DEPENDENCY_LICENSE_MESSAGES.categories, ...messages?.categories },
    policy: { ...DEPENDENCY_LICENSE_MESSAGES.policy, ...messages?.policy },
  }
  const [inner, setInner] = React.useState(defaultValue)
  const [kept, setKept] = React.useState<Set<string>>(() => new Set())
  const [pinned, setPinned] = React.useState<Record<string, string>>({})
  const [asked, setAsked] = React.useState(false)
  const [pending, setPending] = React.useState(false)
  const rootRef = React.useRef<HTMLDivElement>(null)
  const baseId = React.useId()
  const addRef = React.useRef<HTMLButtonElement>(null)
  const deps = (Array.isArray(value ?? inner) ? (value ?? inner) : []).filter((d): d is DependencyInfo => !!d && typeof d.name === "string")
  const reviews = deps.map((dep) => reviewDependency(dep, policy))
  const open = reviews.map((review, i) => (review.level === "warn" || review.level === "block") && !kept.has(deps[i].name))
  const blocked = reviews.filter((review, i) => open[i] && review.level === "block").length
  const toReview = open.filter(Boolean).length
  const project = policy.project && !/^(proprietary|closed)$/i.test(policy.project) ? policy.project : t.proprietary

  const commit = (next: DependencyInfo[]) => {
    if (value === undefined) setInner(next)
    onValueChange?.(next)
    setAsked(false)
  }

  /** After a fix, go to the next row that still needs a decision, else Add, else the list. */
  const focusAfter = (index: number) =>
    requestAnimationFrame(() => {
      const rows = Array.from(rootRef.current?.querySelectorAll<HTMLElement>("[data-row]") ?? [])
      const next = rows.slice(index).find((row) => row.querySelector("[data-fix]"))
      ;(next?.querySelector<HTMLElement>("[data-fix]") ?? addRef.current ?? rootRef.current)?.focus()
    })

  const add = async () => {
    if (toReview && !asked) {
      setAsked(true)
      rootRef.current?.querySelector<HTMLElement>("[data-fix]")?.focus()
      return
    }
    if (!onAdd || pending) return
    setPending(true)
    try {
      await onAdd(deps)
    } catch {
      // The caller reports install failures; the button becomes usable again.
    } finally {
      setPending(false)
    }
  }

  return (
    <div ref={rootRef} tabIndex={-1} data-slot="dependency-license-check" data-state={blocked ? "blocked" : toReview ? "review" : "ok"} className={cn("w-full max-w-md space-y-3 text-sm outline-none", className)} {...props}>
      <div className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1">
        <h3 className="font-medium">{t.heading}</h3>
        <p className="flex items-center gap-1.5 text-xs text-muted-foreground">
          <Scale aria-hidden className="size-3.5" />
          {project} · {t.policy[policy.distribution ?? "distributed"]}
        </p>
      </div>
      <ul className="divide-y rounded-md border">
        {deps.map((dep, index) => {
          const review = reviews[index]
          const needsDecision = open[index]
          const declared = licenseText(dep.license)
          const nameId = `${baseId}-${index}`
          const reason = fill(t.reasons[review.reason] ?? "", { license: review.chosen || declared, chosen: review.chosen, project })
          const level: LicenseLevel = needsDecision ? review.level : review.level === "note" ? "note" : "ok"
          return (
            <li key={`${dep.name}#${index}`} data-row data-level={review.level} className="space-y-1.5 p-3">
              <div className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
                <Package aria-hidden className="size-4 shrink-0 text-muted-foreground" />
                <span id={nameId} className="min-w-0 truncate font-mono text-xs font-medium" title={`${dep.name}@${dep.version}`}>
                  {dep.name}
                  <span className="text-muted-foreground">@{dep.version}</span>
                </span>
                {dep.dev && <span className="rounded border px-1 text-[11px] text-muted-foreground">{t.dev}</span>}
                <span className={cn("ml-auto max-w-full truncate rounded-full px-2 py-0.5 text-xs font-medium", needsDecision || review.category === "permissive" ? CHIP[review.category] : "bg-muted text-muted-foreground")} title={declared}>
                  {review.chosen || t.categories.missing}
                  <span className="sr-only"> ({t.categories[review.category]})</span>
                </span>
              </div>
              {pinned[dep.name] && (
                <p className="flex gap-1.5 text-xs text-emerald-700 dark:text-emerald-400">
                  <Pin aria-hidden className="mt-0.5 size-3.5 shrink-0" />
                  {pinned[dep.name]}
                </p>
              )}
              {(reason || review.change) && (
                <div className={cn("flex gap-1.5 text-xs", TEXT[level])}>
                  {review.level === "block" && needsDecision ? <ShieldAlert aria-hidden className="mt-0.5 size-3.5 shrink-0" /> : <Scale aria-hidden className="mt-0.5 size-3.5 shrink-0" />}
                  <div className="min-w-0 space-y-1">
                    {review.change && (
                      <p className="break-words font-medium">
                        {fill(review.change.fromVersion ? t.changed : t.changedNoVersion, { from: review.change.from, version: review.change.fromVersion ?? "" })}
                      </p>
                    )}
                    {reason && <p className="break-words">{reason}</p>}
                    {needsDecision && (
                      <div className="flex flex-wrap gap-2 pt-0.5">
                        {review.change?.fromVersion && (
                          <button
                            type="button"
                            data-fix
                            aria-describedby={nameId}
                            onClick={() => {
                              const { from, fromVersion = "" } = review.change!
                              commit(deps.map((d, i) => (i === index ? { ...d, version: fromVersion, license: dep.previousLicense, previousVersion: undefined, previousLicense: undefined } : d)))
                              setPinned((p) => ({ ...p, [dep.name]: fill(t.pinned, { version: fromVersion, from }) }))
                              focusAfter(index)
                            }}
                            className={fixClass}
                          >
                            <Pin aria-hidden className="size-3.5" />
                            {fill(t.pin, { version: review.change.fromVersion })}
                          </button>
                        )}
                        <button
                          type="button"
                          data-fix={review.change?.fromVersion ? undefined : ""}
                          aria-describedby={nameId}
                          onClick={() => {
                            commit(deps.filter((_, i) => i !== index))
                            focusAfter(index)
                          }}
                          className={review.level === "block" ? blockFixClass : fixClass}
                        >
                          <Trash2 aria-hidden className="size-3.5" />
                          {t.remove}
                        </button>
                        <button
                          type="button"
                          onClick={() => {
                            setKept((k) => new Set(k).add(dep.name))
                            focusAfter(index + 1)
                          }}
                          aria-describedby={nameId}
                          className={ghostClass}
                        >
                          {t.keep}
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </li>
          )
        })}
      </ul>
      <div className="flex flex-wrap items-center justify-between gap-3">
        <p aria-live="polite" className={cn("flex items-center gap-1.5 text-sm", blocked ? TEXT.block : toReview ? TEXT.warn : "text-emerald-700 dark:text-emerald-400")}>
          {toReview ? <ShieldAlert aria-hidden className="size-4 shrink-0" /> : <CircleCheck aria-hidden className="size-4 shrink-0" />}
          {blocked ? fill(t.summaryBlocked, { count: blocked, total: deps.length }) : toReview ? fill(t.summaryReview, { count: toReview, total: deps.length }) : t.summaryOk}
        </p>
        {onAdd && (
          <button
            ref={addRef}
            type="button"
            onClick={add}
            disabled={pending || !deps.length}
            className={cn(
              "ml-auto inline-flex h-9 shrink-0 items-center gap-2 rounded-md px-4 text-sm font-medium outline-none transition-colors focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:opacity-60",
              asked && toReview ? "bg-red-700 text-white hover:bg-red-800 dark:bg-red-400 dark:text-red-950" : "bg-primary text-primary-foreground hover:bg-primary/90",
            )}
          >
            {pending && <Loader2 aria-hidden className="size-4 animate-spin" />}
            {asked && toReview ? t.addAnyway : t.add}
          </button>
        )}
      </div>
    </div>
  )
}

// Bollard UI — dependency-license-check · MIT licence · https://bollard-ui.vercel.app/components/dependency-license-check

/** How a license constrains the code that uses it, from least to most restrictive. */
export type LicenseCategory = "permissive" | "weak" | "unknown" | "strong" | "network" | "source-available" | "missing"

const RANK: Record<LicenseCategory, number> = { permissive: 0, weak: 1, unknown: 2, strong: 3, network: 4, "source-available": 4, missing: 5 }

const RULES: [RegExp, LicenseCategory][] = [
  [/^(none|noassertion|unlicensed|all rights reserved)$/, "missing"],
  [/^agpl/, "network"],
  [/^(sspl|busl|bsl-1\.1|elastic-|rsal|commons-clause|polyform|cc-by-nc|confluent|fsl-)/, "source-available"],
  [/^(lgpl|mpl|epl|cddl|cpl|ms-rl|ms-pl|eupl-1\.0)/, "weak"],
  [/^(gpl|eupl|osl|cc-by-sa|sleepycat|rpl|qpl)/, "strong"],
  [/^(mit|isc|bsd|0bsd|apache|unlicense$|cc0|zlib|python|psf|blueoak|bsl-1\.0|wtfpl|artistic-2|x11|cc-by-[34]|postgresql|upl|ncsa|unicode|w3c|afl|hpnd|curl|libpng|ftl)/, "permissive"],
]

const ALIASES: Record<string, string> = {
  "apache 2.0": "apache-2.0", "apache 2": "apache-2.0", "apache2": "apache-2.0", "apache-2": "apache-2.0", "apache license 2.0": "apache-2.0",
  gplv2: "gpl-2.0", gplv3: "gpl-3.0", gpl2: "gpl-2.0", gpl3: "gpl-3.0", "gpl v3": "gpl-3.0", "gpl v2": "gpl-2.0",
  agplv3: "agpl-3.0", lgplv3: "lgpl-3.0", lgplv2: "lgpl-2.1", "mpl 2.0": "mpl-2.0", "the unlicense": "unlicense", "public domain": "unlicense",
}

/** npm's "SEE LICENSE IN <file>", LicenseRef- ids and words for paid terms: a license exists, but not a standard one. */
export const CUSTOM_LICENSE = /^(see licen[cs]e in\b|licenseref-|custom$|proprietary$|commercial$)/i

const LINK_EXCEPTIONS = /classpath|linking|gcc|autoconf|bison|libtool|llvm|font|openjdk|universal-foss/

const normal = (id: string) => {
  const lower = id.trim().toLowerCase().replace(/\s+/g, " ")
  return ALIASES[lower] ?? lower
}

/** The category of one license id (MIT, GPL-3.0-or-later, Apache 2.0, UNLICENSED…). */
export function categorize(id: string): LicenseCategory {
  const value = normal(id)
  if (!value) return "missing"
  return RULES.find(([pattern]) => pattern.test(value))?.[1] ?? "unknown"
}

/**
 * A package.json `license` as found in the wild: an SPDX string, or the deprecated
 * `{ type, url }` object and `licenses: [{ type }]` array that old packages still ship.
 */
export type LicenseField = string | { type?: string } | (string | { type?: string })[] | null | undefined

/** Flattens any `LicenseField` to one expression; an array is a choice (OR). */
export function licenseText(license: LicenseField): string {
  const one = (l: unknown) => (typeof l === "string" ? l.trim() : l && typeof l === "object" && typeof (l as { type?: unknown }).type === "string" ? (l as { type: string }).type.trim() : "")
  if (Array.isArray(license)) {
    const parts = license.map(one).filter(Boolean)
    return parts.length > 1 ? parts.map((p) => `(${p})`).join(" OR ") : (parts[0] ?? "")
  }
  return one(license)
}

export interface LicenseReading {
  category: LicenseCategory
  /** The license you would actually use it under: the most permissive side of an OR. */
  chosen: string
}

/**
 * Reads an SPDX expression ("MIT OR GPL-3.0", "(LGPL-2.1 AND BSD-3-Clause)", "GPL-2.0 WITH
 * Classpath-exception-2.0"). OR takes the friendliest choice, AND the strictest part. An old
 * npm `licenses` array counts as a choice. Malformed text is read as one id; it never throws.
 */
export function readLicense(license: LicenseField): LicenseReading {
  const text = licenseText(license)
  if (!text) return { category: "missing", chosen: "" }
  if (CUSTOM_LICENSE.test(text)) return { category: "unknown", chosen: text }

  const tokens = text.match(/\(|\)|[^\s()]+/g) ?? []
  let pos = 0
  const worse = (a: LicenseReading, b: LicenseReading) => (RANK[b.category] > RANK[a.category] ? b : a)
  const better = (a: LicenseReading, b: LicenseReading) => (RANK[b.category] < RANK[a.category] ? b : a)
  const isOp = (token: string | undefined, op: string) => token?.toUpperCase() === op

  const atom = (): LicenseReading => {
    const token = tokens[pos++]
    if (token === undefined) throw new Error("end")
    if (token === "(") {
      const inner = either()
      if (tokens[pos++] !== ")") throw new Error("paren")
      return inner
    }
    if (token === ")" || isOp(token, "AND") || isOp(token, "OR") || isOp(token, "WITH")) throw new Error("operator")
    const id = token.replace(/\+$/, "")
    let category = categorize(id)
    if (isOp(tokens[pos], "WITH")) {
      pos++
      const exception = (tokens[pos++] ?? "").toLowerCase()
      if (category === "strong" && LINK_EXCEPTIONS.test(exception)) category = "weak"
    }
    return { category, chosen: token }
  }
  const both = (): LicenseReading => {
    let result = atom()
    while (isOp(tokens[pos], "AND")) {
      pos++
      const next = atom()
      result = { ...worse(result, next), chosen: `${result.chosen} AND ${next.chosen}` }
    }
    return result
  }
  const either = (): LicenseReading => {
    let result = both()
    while (isOp(tokens[pos], "OR") || tokens[pos] === "/") {
      pos++
      result = better(result, both())
    }
    return result
  }

  try {
    const result = either()
    if (pos !== tokens.length) throw new Error("trailing")
    return result
  } catch {
    return { category: categorize(text), chosen: text }
  }
}

/** A dependency being added, as your package manager or registry reports it. */
export interface DependencyInfo {
  name: string
  version: string
  /** SPDX expression from package.json (or an old `licenses` array). Missing means none was declared. */
  license?: LicenseField
  /** Only used in development and never shipped (devDependencies, build tools). */
  dev?: boolean
  /** The version you are on now or the last version before this one, to catch a relicense. */
  previousVersion?: string
  /** The license of `previousVersion`. */
  previousLicense?: LicenseField
}

/** Your project's rules. */
export interface LicensePolicy {
  /** "proprietary" for closed-source code, or your project's own SPDX license (MIT, GPL-3.0…). */
  project?: string
  /** How your code reaches people: shipped to them (apps, libraries, browser bundles), run only as a hosted service, or internal use. */
  distribution?: "distributed" | "saas" | "internal"
  /** License ids your team has already approved. */
  allow?: string[]
  /** License ids your team never allows. */
  deny?: string[]
}

export type LicenseLevel = "ok" | "note" | "warn" | "block"
export type LicenseReason =
  | "ok" | "chosen" | "devOnly" | "allowed" | "denied" | "missing" | "unknown" | "weak"
  | "gpl" | "gplSaas" | "agpl" | "copyleftInternal" | "copyleftInOpenSource" | "sourceAvailable" | "sourceAvailableSaas"
  | "custom" | "incompatible"

export interface LicenseReview {
  level: LicenseLevel
  reason: LicenseReason
  category: LicenseCategory
  chosen: string
  /** Set when the license became more restrictive (or vanished) since `previousVersion`. */
  change?: { from: string; fromCategory: LicenseCategory; fromVersion?: string }
}

const LEVELS: LicenseLevel[] = ["ok", "note", "warn", "block"]
/** "AGPL-3.0", "AGPL-3.0-only", "agpl-3.0-or-later" and "AGPL-3.0+" are one entry on a list. */
const base = (id: string) => normal(id).replace(/\+$|-only$|-or-later$/, "")
/** The ids in the side of the expression you would use ("MIT AND BSD-3-Clause" → both). */
const idsOf = (chosen: string) => chosen.split(/\s+AND\s+/i).map((id) => id.replace(/[()]/g, "").trim()).filter(Boolean)
const onList = (list: string[] | undefined, id: string) => (list ?? []).some((entry) => base(entry) === base(id))
/** Denied when any license you'd be bound by is denied; allowed only when every one of them is. */
const denied = (list: string[] | undefined, chosen: string) => !!chosen && idsOf(chosen).some((id) => onList(list, id))
const allowed = (list: string[] | undefined, chosen: string) => !!chosen && idsOf(chosen).every((id) => onList(list, id))

type Gpl = { family: "gpl" | "lgpl" | "agpl"; version: number; later: boolean }
const gplOf = (id: string): Gpl | null => {
  const m = normal(id).match(/^(a|l)?gpl-?(\d(?:\.\d)?)(?:\.0)?(-or-later|\+)?/)
  return m ? { family: m[1] === "a" ? "agpl" : m[1] === "l" ? "lgpl" : "gpl", version: Number(m[2]), later: !!m[3] } : null
}
/** Free licenses the FSF lists as GPL-incompatible (www.gnu.org/licenses/license-list.html). */
const GPL_INCOMPATIBLE = /^(epl-|cddl|mpl-1|ms-pl|ms-rl|cpl-|osl-|afl-|apache-1|php-|bsd-4|cecill-[bc]|ipl-|sissl|qpl|zpl-1|openssl$)/
/** Also incompatible with GPLv2-only (patent and attribution terms GPLv2 lacks). */
const GPL2_INCOMPATIBLE = /^(apache-2|ecl-2|ftl$|xfree86-1\.1)/

/** Can code under `id` be combined with a project under the GNU license `project`? */
function gplCompatible(project: Gpl, id: string) {
  const value = normal(id)
  if (GPL_INCOMPATIBLE.test(value)) return false
  const v2only = project.version < 3 && !project.later
  if (v2only && GPL2_INCOMPATIBLE.test(value)) return false
  const dep = gplOf(value)
  if (!dep) return true
  if (v2only && dep.version >= 3) return false
  if (project.version >= 3 && dep.family === "gpl" && dep.version < 3 && !dep.later) return false
  if (dep.family === "agpl" && project.version < 3 && !project.later) return false
  return true
}

/** Whether a dependency fits the policy, and why. Pure, so it can run in CI or on a server. */
export function reviewDependency(dep: DependencyInfo, policy: LicensePolicy = {}): LicenseReview {
  const { category, chosen } = readLicense(dep?.license)
  const project = (policy.project ?? "proprietary").trim()
  const closed = /^(proprietary|closed|unlicensed|private|commercial)$/i.test(project) || readLicense(project).category === "missing"
  const projectCopyleft = !closed && RANK[readLicense(project).category] >= RANK.strong && readLicense(project).category !== "source-available"
  const projectGpl = projectCopyleft ? gplOf(project) : null
  const distribution = policy.distribution ?? "distributed"
  const verdict = (level: LicenseLevel, reason: LicenseReason): LicenseReview => ({ level, reason, category, chosen })

  let review: LicenseReview
  if (denied(policy.deny, chosen)) review = verdict("block", "denied")
  else if (allowed(policy.allow, chosen)) review = verdict("ok", "allowed")
  else if (category === "missing") review = verdict(dep?.dev ? "warn" : "block", "missing")
  else if (category === "unknown") review = verdict("warn", CUSTOM_LICENSE.test(chosen) ? "custom" : "unknown")
  else if (dep?.dev && category !== "permissive") review = verdict("ok", "devOnly")
  else if (category === "source-available") review = verdict(distribution === "saas" ? "block" : "warn", distribution === "saas" ? "sourceAvailableSaas" : "sourceAvailable")
  else if (category === "network" || category === "strong") {
    if (projectCopyleft) review = verdict("ok", "ok")
    else if (!closed) review = verdict("warn", "copyleftInOpenSource")
    else if (distribution === "internal") review = verdict("note", "copyleftInternal")
    else if (category === "network") review = verdict("block", "agpl")
    else review = verdict(distribution === "saas" ? "warn" : "block", distribution === "saas" ? "gplSaas" : "gpl")
  } else if (category === "weak") review = verdict(closed ? "note" : "ok", closed ? "weak" : "ok")
  else review = /\s(OR|\/)\s/i.test(licenseText(dep?.license)) ? verdict("note", "chosen") : verdict("ok", "ok")

  // In a GNU-licensed project, copyleft alone is fine but some licenses can't be combined with it.
  if (projectGpl && !dep?.dev && (review.level === "ok" || review.level === "note") && review.reason !== "allowed" && !compatibleChoice(projectGpl, licenseText(dep?.license)))
    review = verdict(distribution === "distributed" ? "block" : "warn", "incompatible")

  if (dep?.previousLicense !== undefined) {
    const before = readLicense(dep.previousLicense)
    if (RANK[category] > RANK[before.category]) {
      review.change = { from: before.chosen || licenseText(dep.previousLicense), fromCategory: before.category, fromVersion: dep.previousVersion }
      if (LEVELS.indexOf(review.level) < LEVELS.indexOf("warn")) review.level = "warn"
    }
  }
  return review
}

/** SPDX precedence (WITH > AND > OR): true when some way of using `expression` is fully compatible. Unparseable text counts as compatible, leaving it to the other checks. */
function compatibleChoice(project: Gpl, expression: string) {
  const tokens = expression.match(/\(|\)|[^\s()]+/g) ?? []
  let pos = 0
  const op = (word: string) => tokens[pos]?.toUpperCase() === word
  const atom = (): boolean => {
    const token = tokens[pos++]
    if (token === "(") {
      const inner = either()
      pos++
      return inner
    }
    if (op("WITH")) pos += 2
    return !token || gplCompatible(project, token.replace(/\+$/, "-or-later"))
  }
  const both = (): boolean => {
    let ok = atom()
    while (op("AND")) {
      pos++
      ok = atom() && ok
    }
    return ok
  }
  const either = (): boolean => {
    let ok = both()
    while (op("OR") || tokens[pos] === "/") {
      pos++
      ok = both() || ok
    }
    return ok
  }
  try {
    return either()
  } catch {
    return true
  }
}
